function Auth({onAuth}:{onAuth:(session:Session)=>void}) {
  const [mode,setMode] = useState<"login"|"signup">("login");
  const [email,setEmail] = useState(""); const [password,setPassword] = useState(""); const [username,setUsername] = useState("");
  const [error,setError] = useState(""); const [busy,setBusy] = useState(false);
  async function submit(e:FormEvent) {
    e.preventDefault(); setBusy(true); setError("");
    try {
      if (mode === "signup") {
        const name = username.trim().toLowerCase();
        if (!/^[a-z0-9_]{3,24}$/.test(name)) throw Error("Username must be 3–24 lowercase letters, numbers or underscores.");
        const {data,error} = await supabase.auth.signUp({email,password,options:{data:{username:name}}});
        if (error) throw error;
        if (!data.session) { setError("Account created. Confirm your email, then sign in."); setMode("login"); return; }
        onAuth(data.session);
      } else {
        const {data,error} = await supabase.auth.signInWithPassword({email,password});
        if (error) throw error;
        onAuth(data.session!);
      }
    } catch(e) { setError(explainAuthError(e)); }
    finally { setBusy(false); }
  }
  return <main className="auth-page"><section className="auth-card"><div className="brand"><span className="brand-mark"><img src="/relay.svg" alt="" width={30} height={30}/></span> Relay</div><h1>{mode==="login"?"Welcome back":"Create your account"}</h1><div className="auth-switch"><button className={mode==="login"?"selected":""} onClick={()=>{setMode("login");setError("");}}>Sign in</button><button className={mode==="signup"?"selected":""} onClick={()=>{setMode("signup");setError("");}}>Create account</button></div><form onSubmit={submit}>{mode==="signup"&&<label>Username<input value={username} onChange={e=>setUsername(e.target.value)} placeholder="your_username" required minLength={3} maxLength={24}/></label>}<label>Email address<input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com" required/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="At least 6 characters" required minLength={6}/></label>{error&&<p className="error">{error}</p>}<button className="primary full" disabled={busy}>{busy?"Please wait…":mode==="login"?"Sign in":"Create account"}</button></form></section></main>;
}
